def test_dict_token_initializes_child_mappings_and_returns_values():
    class LeafToken:
        def __init__(self, value):
            self._value = value

        def _get_value(self):
            return self._value

    key_one = LeafToken("first")
    key_two = LeafToken("second")
    value_one = LeafToken(1)
    value_two = LeafToken(2)

    token = DictToken(
        {key_one: value_one, key_two: value_two},
        start_index=0,
        end_index=10,
        content="{'first': 1, 'second': 2}",
